const e = $json;
const o = e.order;
const DAY = 86400000;
const dayDiff = (a, b) =>
  Math.round((Date.parse(a.slice(0, 10) + 'T00:00:00Z') - Date.parse(b.slice(0, 10) + 'T00:00:00Z')) / DAY);

const days = (o && o.delivered_date) ? dayDiff(e.received_at, o.delivered_date) : null;
const ic = e.item_condition;

const issueCondition = ['damaged', 'wrong_item', 'missing_item'].includes(ic);
const complaintFlow = e.intent === 'complaint' || (e.intent === 'return_refund' && issueCondition);
const returnFlow = e.intent === 'return_refund' && !issueCondition;
const need_photos = complaintFlow && issueCondition && !e.has_attachments;

let policy_result = 'not_applicable';
let facts = [];
let needs_human = !!e.needs_human;
let refund_amount = null;
let refund_method = null;

if (o && returnFlow) {
  if (o.status !== 'delivered') {
    policy_result = 'not_delivered_yet';
    facts.push('Order is not delivered yet. Returns can be raised only after delivery; cancellation is possible only before dispatch.');
  } else {
    const reasons = [];
    if (ic === 'used') reasons.push('the product was opened or used (only unused, unopened, sealed items can be returned)');
    if (days > 7) reasons.push('it was delivered ' + days + ' days ago (return window is 7 days from delivery)');
    if (reasons.length) {
      policy_result = 'not_eligible';
      facts.push('Return NOT eligible: ' + reasons.join('; ') + '.');
    } else if (ic === 'unopened') {
      policy_result = 'eligible';
      refund_amount = o.subtotal;
      refund_method = o.payment_method === 'cod'
        ? 'UPI or bank transfer (ask for details only after pickup is completed)'
        : 'original payment method within 5-7 business days after quality check';
      facts.push('Return eligible: delivered ' + days + ' days ago, unopened. Free reverse pickup in 2-3 business days. Refund INR ' + refund_amount + ' (items only, assuming the full order is returned; shipping and COD fees are non-refundable) via ' + refund_method + '.');
      facts.push('Do not mention return labels or packaging; our team arranges the pickup.');
      if ((o.items || []).some(i => /kit/i.test(i.name))) {
        facts.push('Kit products must be returned as a complete set.');
      }
    } else {
      policy_result = 'needs_confirmation';
      needs_human = true;
      facts.push('Cannot confirm the item is unopened and sealed. Ask the customer to confirm.');
    }
  }
}

if (o && complaintFlow) {
  const fix = {
    damaged: 'free replacement or full refund, customer\'s choice',
    wrong_item: 'pick up the wrong item and send the correct one at no cost',
    missing_item: 'ship the missing item or refund its value, after checking the packing weight record'
  };
  if (fix[ic]) {
    if (days === null || days > 1) {
      policy_result = 'outside_48h';
      needs_human = true;
      facts.push('Reported ' + days + ' days after delivery; the policy window is 48 hours. Hand over to a human.');
    } else {
      policy_result = 'eligible_after_verification';
      facts.push('Reported within 48 hours of delivery. After verification by our team: ' + fix[ic] + '. The 7-day/unopened rule does not apply.');
      facts.push('Do not quote any refund amount. Do not say the issue is verified or that a replacement has been dispatched. Do not include any tracking link (the order is already delivered). Say a team member will verify and confirm within 24 business hours.');
      if (need_photos) {
        facts.push('Ask the customer to send photos of the product and the outer box.');
      } else {
        facts.push('Photos already received; a team member must verify them.');
        needs_human = true;
      }
    }
  } else {
    policy_result = 'general_complaint';
    needs_human = true;
    facts.push('General complaint; a human should handle it.');
  }
}

if (e.sentiment === 'angry') needs_human = true;

const ticket_needed = e.intent === 'return_refund' || e.intent === 'complaint';
const ticket_priority = !ticket_needed ? '' : (complaintFlow ? 'High' : 'Medium');

return { json: {
  ...e,
  days_since_delivery: days,
  policy_result,
  policy_facts: facts.join(' '),
  refund_amount,
  refund_method,
  need_photos,
  ticket_needed,
  ticket_priority,
  needs_human
} };

const e = $json;
const SIGN = "\n\nWarm regards,\nTeam Kesar";
const text = ((e.subject || '') + ' ' + (e.body || '') + ' ' + (e.summary || '') + ' ' + (e.reason || '')).toLowerCase();

let reply = '';
let action = 'held_for_human';
let needs_human = true;
let note = 'other_unclassified';

if (/spam|seo|backlink|rank(ing)? (your|ur) (website|site)/.test(text)) {
  action = 'logged_only';
  needs_human = false;
  note = 'spam';
} else if (/collab|partnership|influencer|wholesale|press|sponsor|ambassador/.test(text)) {
  reply = "Hi,\n\nThank you for your interest in Kesar & Co. For collaboration, partnership, wholesale and press enquiries, please write to our partnerships team at partnerships@kesarandco.example." + SIGN;
  action = 'held_for_human';
  needs_human = true;
  note = 'partnership_enquiry';
} else if (/thank|thanks|dhanyavaad|shukriya/.test(text) && !/\?/.test(e.body || '') && e.sentiment !== 'negative' && e.sentiment !== 'angry') {
  action = 'logged_only';
  needs_human = false;
  note = 'thank_you';
} else {
  reply = "Hi,\n\nThank you for reaching out. We have passed your message to our support team, and they will get back to you shortly." + SIGN;
  note = e.reason || 'needs_human_review';
}

return { json: { ...e, order_found: false, reply_draft: reply, action_taken: action, needs_human, ticket_id: '', notes: note } };

// identity comes from the workflow, never from the model's input
const e = $('Policy Check').last().json;
if (!e.safe_to_share || !e.order) {
  return JSON.stringify({ error: 'Order not available for this sender. Do not share any order details.' });
}
const o = e.order;
return JSON.stringify({
  order_id: o.order_id,
  status: o.status,
  items: o.items.map(i => i.qty + ' x ' + i.name),
  payment_method: o.payment_method,
  total: o.total,
  courier: o.courier,
  tracking_url: o.tracking_url,
  shipped_date: o.shipped_date,
  estimated_delivery: o.estimated_delivery,
  delivered_date: o.delivered_date,
  cancelled_date: o.cancelled_date,
  cancellation_reason: o.cancellation_reason,
  refund_status: o.refund_status
});

const FAQ = {
shipping: `SHIPPING: Orders are dispatched within 1-2 business days (Mon-Sat, excluding public holidays). Delivery after dispatch: Metro cities (Delhi NCR, Mumbai, Bengaluru, Chennai, Kolkata, Hyderabad, Pune): 2-4 business days. Rest of India: 4-6 business days. North-East states, Jammu & Kashmir, Ladakh, Andaman & Nicobar, Lakshadweep: 6-8 business days. Shipping is free on orders of Rs 999 and above; below Rs 999 a flat Rs 79 shipping fee applies. Courier partners: SwiftShip and BharatExpress; a tracking link is emailed at dispatch. We do not ship outside India. The delivery address cannot be changed once an order is dispatched.`,
cod: `COD: Cash on Delivery is available on orders up to Rs 5,000. A Rs 49 COD handling fee applies and is not refundable. Please keep exact change ready; delivery partners may not carry change.`,
cancellation: `CANCELLATION: Orders can be cancelled only before dispatch. Once dispatched, the customer must wait for delivery and raise a return instead. If we cancel an order (for example, out of stock), prepaid orders are refunded automatically to the original payment method within 5-7 business days.`,
returns: `RETURNS: Returns are accepted within 7 days of delivery. Items must be unused, unopened and with the seal intact. For hygiene reasons we cannot accept opened or used products, including "didn't suit me" or "didn't see results" cases. To start a return, the customer replies with the order ID. We arrange a free reverse pickup within 2-3 business days. Combo or kit products (e.g. Bridal Glow Kit) must be returned as a complete set.`,
damaged: `DAMAGED, LEAKING, WRONG OR MISSING ITEMS: Report within 48 hours of delivery, with photos of the product and the outer box. After verification we offer a free replacement or a full refund (customer's choice). The 7-day / unopened rule does not apply. Wrong item: we pick up the wrong item and send the correct one at no cost. Missing item: we verify against the packing weight record and ship the missing item or refund its value.`,
refunds: `REFUNDS: Prepaid orders are refunded to the original payment method within 5-7 business days after the returned item passes quality check. COD orders are refunded via UPI or bank transfer; we ask the customer for a UPI ID (or account holder name, account number and IFSC) after the pickup is completed. Shipping fees and COD fees are non-refundable, except for damaged, wrong or missing item cases where the full amount paid is refunded. We never ask for an OTP, card PIN, CVV or password.`,
products: `PRODUCTS: All products are cruelty-free, paraben-free, made in India, shelf life 24 months from manufacture (12 months after opening).
- Saffron Glow Face Serum 30 ml, Rs 1,299: Saffron + Vitamin C. Lightweight, non-greasy, suitable for all skin types including oily. Vegan. Use AM/PM after cleansing.
- Kumkumadi Night Oil 15 ml, Rs 1,149: Traditional kumkumadi tailam blend. Best for normal to dry skin. Not recommended for very oily or acne-prone skin. Night use only. Vegan.
- Ubtan Face Pack 100 g, Rs 699: Turmeric, chickpea flour, sandalwood. Mix with water or rose water. Use 2x a week. Vegan.
- Rose Water Toner 200 ml, Rs 899: Steam-distilled rose water, alcohol-free. Suitable for all skin types. Vegan.
- Bhringraj Hair Oil 200 ml, Rs 649: Bhringraj, amla, coconut oil base. Apply 1 hour before washing. Vegan.
- Sandalwood Body Lotion 250 ml, Rs 749: Sandalwood + shea butter. Contains beeswax, so NOT vegan.
- Aloe Calm Gel 150 g, Rs 499: 92% aloe vera. Soothing, suitable for all skin types. Vegan.
- Bridal Glow Kit, Rs 3,499: Contains Saffron Glow Serum, Kumkumadi Night Oil, Ubtan Face Pack and Rose Water Toner. Start 4-6 weeks before the event.`,
safety: `PRODUCT SAFETY & MEDICAL: Our products are cosmetics, not medicines, and are not intended to diagnose, treat or cure any skin or medical condition. We recommend a patch test (inner forearm, 24 hours) before first use. For any skin condition (e.g. eczema, psoriasis, severe acne), pregnancy or allergies, consult a dermatologist or doctor before use. Support must not give medical advice or make claims about curing or treating conditions. If a customer reports a reaction, advise them to stop using the product immediately, consult a doctor, and escalate to a human.`,
contact: `CONTACT: Email support@kesarandco.example. Support hours Mon-Sat, 10:00-19:00 IST; we aim to reply within 24 business hours. Business and partnership enquiries (influencers, wholesale, press): partnerships@kesarandco.example.`
};
const KEYS = {
shipping: ['ship','deliver','dispatch','courier','track','address','how long','days','outside india','metro'],
cod: ['cod','cash','handling'],
cancellation: ['cancel'],
returns: ['return','exchange','pickup','unopened','seal','kit'],
damaged: ['damag','leak','wrong','missing','crack','broken','photo','replace'],
refunds: ['refund','money back','upi','otp','pin','cvv','password','bank'],
products: ['product','vegan','oily','dry skin','skin type','ingredient','price','serum','oil','toner','lotion','gel','pack','kit','shelf','saffron','kumkumadi','ubtan','rose','bhringraj','sandalwood','aloe','bridal','cruelty','paraben'],
safety: ['eczema','medical','cure','treat','allerg','pregnan','rash','reaction','patch','doctor','psoriasis','acne','dermatolog'],
contact: ['contact','hours','partnership','wholesale','press','influenc','collab','support']
};
const q = String(query || '').toLowerCase();
const scored = Object.keys(KEYS)
  .map(k => ({ k, s: KEYS[k].filter(w => q.includes(w)).length }))
  .filter(x => x.s > 0)
  .sort((a, b) => b.s - a.s)
  .slice(0, 2);
if (!scored.length) {
  return 'NO MATCH in the FAQ. Do not answer from your own knowledge. Say a team member will follow up within 24 business hours.';
}
return scored.map(x => FAQ[x.k]).join('\n\n');

const item = $('Merge Branches').first().json;
const rows = $('Get Tickets').all().map(i => i.json).filter(r => r && r.ticket_id);

if (!item.ticket_needed) {
  return [{ json: { ...item, ticket_id: '', ticket_action: 'none' } }];
}

const rank = { Low: 1, Medium: 2, High: 3 };
const orderId = item.order_id;
const when = item.received_at;
const line = item.email_id + ': ' + (item.summary || '');

const open = rows.find(r =>
  r.order_id === orderId && String(r.status || '').toLowerCase() !== 'closed'
);

if (open) {
  const ids = String(open.email_ids || '').split(',').map(s => s.trim()).filter(Boolean);
  const alreadyLinked = ids.includes(item.email_id);
  if (!alreadyLinked) ids.push(item.email_id);
  const oldP = open.priority || 'Medium';
  const newP = (rank[item.ticket_priority] || 0) > (rank[oldP] || 0) ? item.ticket_priority : oldP;
  const notes = alreadyLinked
  ? (open.notes || '')
  : (open.notes ? open.notes + ' | ' : '') + when + ' ' + line;

  return [{ json: {
    ...item,
    ticket_id: open.ticket_id,
    ticket_action: 'update',
    ticket_row: {
      ticket_id: open.ticket_id,
      updated_at: when,
      email_ids: ids.join(', '),
      priority: newP,
      notes
    }
  } }];
}

let id = 'TKT-' + String(orderId || item.email_id).replace('KC-', '');
const taken = new Set(rows.map(r => r.ticket_id));
let n = 2;
const base = id;
while (taken.has(id)) id = base + '-' + n++;

return [{ json: {
  ...item,
  ticket_id: id,
  ticket_action: 'create',
  ticket_row: {
    ticket_id: id,
    created_at: when,
    updated_at: when,
    order_id: orderId,
    customer_email: item.from_email,
    email_ids: item.email_id,
    intent: item.intent,
    priority: item.ticket_priority || 'Medium',
    status: 'Open',
    summary: item.summary,
    notes: line + (item.policy_result && item.policy_result !== 'not_applicable' ? ' | policy: ' + item.policy_result : '')
  }
} }];

let d;
try {
  d = $('Ticket Decision').item.json;
} catch (e) {
  d = $('Ticket Decision').last().json;
}
return { json: d };

const e = $json;
const SIGN = "\n\nWarm regards,\nTeam Kesar";

let flagged = e.injection_detected === true;
if (!flagged) {
  try { flagged = $('Policy Check').item.json.injection_detected === true; } catch (err) {}
}
if (!flagged) {
  const body = String(e.body || '');
  flagged = /ignore (all |any )?(previous|prior|above) instructions|mark (this |it )?as approved|approve (the |my |this )?(refund|return)|you are now|system prompt/i.test(body);
}

if (flagged) {
  return { json: {
    ...e,
    injection_detected: true,
    reply_draft: "Hi,\n\nThank you for reaching out. We have received your request, and our support team will review it and get back to you." + SIGN,
    action_taken: 'held_for_human',
    needs_human: true,
    notes: 'prompt_injection_blocked'
  }};
}
return { json: e };

const e = $json;
return { json: {
  ...e,
  order: null,
  order_found: false,
  safe_to_share: false,
  policy_result: '',
  policy_facts: '',
  ticket_needed: false,
  ticket_priority: ''
}};

