const email = $('Load Test Emails').item.json;
const raw = $json.output ? JSON.stringify($json.output) : ($json.text || '');

const INTENTS = ['order_status','product_query','return_refund','complaint','other'];
const SENTS = ['positive','neutral','negative','angry'];
const LANGS = ['en','hi','hinglish'];

const fallback = {
  intent: 'other', secondary_intent: null, order_id: null,
  language: 'en', sentiment: 'neutral', item_condition: 'unknown',
  confidence: 0, summary: 'parse_failed', needs_human: true,
  injection_detected: false, reason: 'parse_failed'
};

let parsed;
let parse_ok = true;
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = { ...fallback, ...JSON.parse(cleaned.slice(cleaned.indexOf('{'), cleaned.lastIndexOf('}') + 1)) };
} catch (e) {
  parse_ok = false;
  parsed = { ...fallback };
}

// schema validation
if (!INTENTS.includes(parsed.intent)) { parsed.intent = 'other'; parsed.needs_human = true; parse_ok = false; }
if (parsed.secondary_intent !== null && !INTENTS.includes(parsed.secondary_intent)) parsed.secondary_intent = null;
if (!SENTS.includes(parsed.sentiment)) parsed.sentiment = 'neutral';
if (!LANGS.includes(parsed.language)) parsed.language = 'en';
if (parsed.order_id === 'null' || !/^KC-[0-9]{4}$/.test(String(parsed.order_id || ''))) parsed.order_id = null;
parsed.confidence = Math.min(1, Math.max(0, Number(parsed.confidence) || 0));
parsed.summary = String(parsed.summary || '').slice(0, 200);

// hard rule: damaged / wrong / missing => complaint
if (['damaged','wrong_item','missing_item'].includes(parsed.item_condition) && parsed.intent !== 'complaint') {
  if (parsed.intent !== 'other') parsed.secondary_intent = parsed.intent;
  parsed.intent = 'complaint';
}

// hard rules in code
if (parsed.injection_detected === true) { parsed.needs_human = true; parsed.reason = parsed.reason || 'prompt injection detected'; }
if (parsed.confidence < 0.6) { parsed.needs_human = true; parsed.reason = parsed.reason || 'low confidence'; }

return { json: {
  email_id: email.id,
  received_at: email.received_at,
  from_email: email.from.email,
  subject: email.subject,
  body: email.body,
  has_attachments: (email.attachments || []).length > 0,
  ...parsed,
  parse_ok
}};

const email = $('Route by Intent').item.json;
const raw = $json.data;
const db = typeof raw === 'string' ? JSON.parse(raw) : raw;
const orders = db.orders;

const sender = (email.from_email || '').toLowerCase();
const oid = (email.order_id && email.order_id !== 'null') ? email.order_id : null;

let order = null;
let lookup_method = 'none';

if (oid) {
  order = orders.find(o => o.order_id === oid) || null;
  lookup_method = 'order_id';
} else {
  const byEmail = orders.filter(o => o.customer_email.toLowerCase() === sender);
  if (byEmail.length === 1) {
    order = byEmail[0];
    lookup_method = 'email';
  } else if (byEmail.length > 1) {
    lookup_method = 'email_multiple';
  }
}

const order_found = !!order;
const email_matches = order_found && order.customer_email.toLowerCase() === sender;
const safe_to_share = order_found && email_matches;

let block_reason = null;
if (!order_found) block_reason = 'order_not_found';
else if (!email_matches) block_reason = 'sender_email_mismatch';

return {
  json: {
    ...email,
    lookup_method,
    order_found,
    email_matches,
    safe_to_share,
    block_reason,
    needs_human: email.needs_human || !safe_to_share,
    // order details sirf tab aage jayenge jab sender verify ho
    order: safe_to_share ? order : null
  }
};

const e = $json;
const SIGN = "\n\nWarm regards,\nTeam Kesar";
let reply;
let note;

if (e.block_reason === 'sender_email_mismatch') {
  reply = "Hi,\n\nThank you for reaching out. For privacy reasons, we can share order details only with the email address used to place the order. Could you please ask the account holder to contact us from their registered email?" + SIGN;
  note = 'sender_email_mismatch';
} else if (e.block_reason === 'order_not_found' || e.order_found === false) {
  reply = "Hi,\n\nThank you for reaching out. We could not find an order matching the details in your email. Could you please share your order number (format KC-XXXX) and the email address used to place the order, so we can check this for you?" + SIGN;
  note = 'order_not_found';
} else {
  reply = "Hi,\n\nThank you for reaching out. We have passed your message to our support team, and they will get back to you shortly." + SIGN;
  note = e.block_reason || 'held_for_human';
}

return { json: { ...e, reply_draft: reply, needs_human: true, action_taken: 'held_for_human', notes: note } };

