const cur = (() => { try { return $('Validate Classification').first().json; } catch (err) { return {}; } })();
const pick = (name) => { try { return $(name).first().json; } catch (err) { return null; } };

let e = null;
for (const n of ['Product Prep', 'Policy Check']) {
  const c = pick(n);
  if (c && c.email_id === cur.email_id) { e = c; break; }
}
if (!e) e = pick('Policy Check') || {};
const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];

let draft = String($json.output || '');
draft = draft
  .replace(/\\n/g, '\n')
  .replace(/\*\*/g, '')
  .replace(/[\u2010-\u2015\u2212]/g, '-')
  .replace(/[ \t]+\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/\b(\d{4})-(\d{2})-(\d{2})\b/g, (m, y, mo, d) => {
    const name = months[parseInt(mo, 10) - 1];
    return name ? `${parseInt(d, 10)} ${name} ${y}` : m;
  })
  .trim();

// Delivered orders: tracking links make no sense, so drop any sentence containing a link
const delivered = e.order && e.order.status === 'delivered';
if (delivered) {
  draft = draft
    .split(/\n\n/)
    .map(p => {
      if (/^Warm regards,/.test(p)) return p;
      return p.split(/(?<=[.!?])\s+/).filter(s => !/https?:\/\//i.test(s)).join(' ');
    })
    .filter(p => p.trim())
    .join('\n\n')
    .trim();
}

const signOffOk = /Warm regards,\s*\nTeam Kesar\s*$/.test(draft);

return {
  json: {
    ...e,
    reply_draft: draft,
    action_taken: 'reply_drafted',
    needs_human: e.needs_human || !draft || !signOffOk
  }
};
